contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 winnerId, uint256 priorPoints) public {
        require(true);

        address picker = address(this);
        bool admin = c.isAdmin(picker);

        uint256 beforeFighterPoints = c.fighterPoints(winnerId);
        uint256 beforeTotalPoints = c.totalPoints();

        uint256[] memory winners = new uint256[](1);
        winners[0] = winnerId;
        uint256[] memory winnersToPick = new uint256[](c.winnersPerPeriod());
        for (uint256 i = 0; i < winnersToPick.length; i++) {
            winnersToPick[i] = winnerId;
        }

        bool reverted;
        try c.pickWinner(winnersToPick) { reverted = false; } catch { reverted = true; }

        uint256 afterFighterPoints = c.fighterPoints(winnerId);
        uint256 afterTotalPoints = c.totalPoints();

        if (!reverted && admin) {
            assert(afterFighterPoints == 0);
        } else {
            assert(afterFighterPoints == beforeFighterPoints && afterTotalPoints == beforeTotalPoints);
        }
    }
}

