contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 winnerId, uint256 extraWinners) public {
        uint256 wpp = c.winnersPerPeriod();
        require(wpp >= 1 && wpp < 8);
        require(extraWinners == 0 || extraWinners >= wpp);
        require(c.isAdmin(address(this)));

        uint256[] memory winners = new uint256[](wpp);
        for (uint256 i = 0; i < wpp; i++) {
            winners[i] = winnerId + i;
        }

        uint256 ptsBefore = c.fighterPoints(winnerId);
        uint256 totalBefore = c.totalPoints();

        c.pickWinner(winners);

        uint256 ptsAfter = c.fighterPoints(winnerId);
        uint256 totalAfter = c.totalPoints();

        assert(ptsAfter == 0 && totalAfter + ptsBefore <= totalBefore);
    }
    receive() external payable {}
}

