        uint256[] memory winners = new uint256[](2);
        winners[0] = tokenA;
        winners[1] = tokenB;

        bool reverted;
        try c.pickWinner(winners) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            assert(c.isSelectionComplete(prevRound));
        }
    }
}

