contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address newAdmin, bool access, bool initState) public {
        // Setup: make the test contract the owner of c so the onlyOwner check in adjustAdminAccess can be satisfied.
        // The constructor of C sets _ownerAddress to the deployer of C.
        // Here, c was deployed by this InvMutTest contract in the test harness, so msg.sender for all calls on c is this contract,
        // which is also the deployer/owner. Thus we don't strictly need a setup call, but we ensure we operate as owner.
        require(msg.sender == address(this));

        c.adjustAdminAccess(newAdmin, initState);

        bool before = c.isAdmin(newAdmin);

        bool reverted;
        try c.adjustAdminAccess(newAdmin, access) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool after = c.isAdmin(newAdmin);

        assert(!reverted && after == access);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newAdmin, bool access, bool initState) public {
        // This test contract is the deployer/owner of c, so it can call adjustAdminAccess successfully.
        require(address(this) == c._ownerAddress());

        // Set up an arbitrary prior state for isAdmin[newAdmin].
        c.adjustAdminAccess(newAdmin, initState);
        bool before = c.isAdmin(newAdmin);

        // Deciding call: the owner sets isAdmin[newAdmin] to access.
        bool reverted;
        try c.adjustAdminAccess(newAdmin, access) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool afterVal = c.isAdmin(newAdmin);

        assert(!reverted && afterVal == access);
    }

    receive() external payable {}
}

