        c = _c;
    }

    function run(address claimer, uint256[] calldata winners, uint256 newWinnersPerPeriod) public payable {
        require(address(this).balance == 0);

        // Drive the public entry under test first, then set up interesting state.
        c.getUnclaimedRewards(claimer);

        // Only an admin can update winnersPerPeriod; caller is this test contract.
        c.updateWinnersPerPeriod(newWinnersPerPeriod);

        uint256 beforeRoundId = c.roundId();
        uint256 beforeClaimed = c.numRoundsClaimed(claimer);

        uint256 rewardsBefore = c.getUnclaimedRewards(claimer);

        // Advance rounds / clear points by picking winners each round (only admin can).
        for (uint256 r = 0; r < winners.length; r++) {
            require(winners[r] != 0);
            uint256[] memory oneWinner = new uint256[](1);
            oneWinner[0] = winners[r];
            c.pickWinner(oneWinner);
        }

        uint256 rewardsAfter = c.getUnclaimedRewards(claimer);
        uint256 afterRoundId = c.roundId();
        uint256 afterClaimed = c.numRoundsClaimed(claimer);

        // General rule: getUnclaimedRewards is read-only, reports a count that never decreases
        // as rounds advance, and never modifies the caller's claimed-rounds counter.
        assert(
            rewardsAfter >= rewardsBefore &&
            afterClaimed == beforeClaimed &&
            afterRoundId >= beforeRoundId &&
            rewardsAfter <= afterRoundId
        );
    }

    receive() external payable {}
