        c.pickWinner(new uint256[](1));

        // Suppress unused warnings for the winner params while keeping them as inputs.
        require(w0 == w0 && w1 == w1 && w2 == w2 && w3 == w3);

        // Re-read the value under test and the surrounding state.
        uint256 rewardsAfter = c.getUnclaimedRewards(claimer);
        uint256 afterRoundId = c.roundId();
