contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address initialOwner, address newOwner, bool useNonOwnerCaller) public {
        // initialOwner must be the constructor-provided owner address, which is msg.sender (this contract)
        // since the checker deploys c from this test contract. If not, the test's initial invariant is wrong.
        require(initialOwner == address(this));
        require(newOwner != address(0));

        // First, make a transferOwnership call as the current owner.
        // This must succeed because msg.sender is the owner.
        bool firstReverted;
        try c.transferOwnership(newOwner) {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        // After a successful ownership transfer, c's owner must be newOwner.
        // We observe ownership through the fact that a subsequent non-owner caller reverts.
        // But since this contract is the caller for all calls, we cannot easily make a non-owner call
        // from a different address. However, we can make another call to transferOwnership from
        // this contract; after transfer, this contract is no longer the owner unless newOwner == address(this).
        bool secondReverted;
        if (newOwner == address(this)) {
            // newOwner is this contract, so ownership is still effectively held by this contract;
            // another call should succeed.
            try c.transferOwnership(newOwner) {
                secondReverted = false;
            } catch {
                secondReverted = true;
            }
        } else {
            // newOwner is a different address; this contract is no longer the owner,
            // so another call must revert.
            try c.transferOwnership(initialOwner) {
                secondReverted = false;
            } catch {
                secondReverted = true;
            }
        }

        // General rule: when called by the owner, transferOwnership succeeds and updates the owner such that
        // a subsequent call by a non-owner reverts. When newOwner is this contract, ownership remains with
        // this contract, so subsequent calls still succeed.
        assert(
            (firstReverted == false) &&
            ((newOwner == address(this) && secondReverted == false) ||
             (newOwner != address(this) && secondReverted == true))
        );
    }

    receive() external payable {}
}

