contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        uint256 winnerTokenId0,
        uint256 winnerTokenId1,
        uint256 numPoints0,
        uint256 numPoints1,
        string calldata modelURI,
        string calldata modelType,
        uint256 attr0,
        uint256 attr1
    ) public {
        // The test contract is the admin/owner of the fresh c (it deployed c).
        // Configure exactly two winners per period.
        c.updateWinnersPerPeriod(2);

        // Use winner token ids supplied by the caller; in the target deployment the
        // caller (this contract) owns the fighters, so pickWinner will succeed.
        uint256[] memory winners = new uint256[](2);
        winners[0] = winnerTokenId0;
        winners[1] = winnerTokenId1;

        // Add points (only the ranked battle address may, but here addPoints will
        // revert for this contract; we therefore do NOT rely on adding points).
        // Instead choose the deciding call directly: claimRewards.
        //
        // To guarantee the caller is a winner, we must make the caller be an owner
        // of the selected token. Since the test contract deployed c and also owns
        // the FighterFarm used by c, we assume ownership of the supplied winners.
        // pickWinner records ownerOf(token) as winner address.
        c.pickWinner(winners);

        uint32 before = c.numRoundsClaimed(address(this));
        uint256 roundBefore = c.roundId();

        string[] memory uris = new string[](2);
        string[] memory types = new string[](2);
        uint256[2][] memory attrs = new uint256[2][](2);
        uris[0] = modelURI;
        uris[1] = modelURI;
        types[0] = modelType;
        types[1] = modelType;
        attrs[0] = [attr0, attr1];
        attrs[1] = [attr0, attr1];

        bool reverted;
        try c.claimRewards(uris, types, attrs) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: if the caller currently owns both selected winners, the
        // claimRewards call must NOT revert, and the caller's numRoundsClaimed must
        // advance to the current roundId (since there was exactly one unclaimed
        // round containing the caller as a winner).
        uint32 after_ = c.numRoundsClaimed(address(this));
        assert(!reverted && after_ == roundBefore && before == 0);
    }
}

