    ) public {
        // Configure two winners per period; caller is admin (deployed c).
        c.updateWinnersPerPeriod(2);

        // Record two winners for round 0. These tokens are owned by this test
        // contract in the target deployment, so pickWinner succeeds and the
        // caller is recorded as a winner.
        uint256[] memory winners = new uint256[](2);
        winners[0] = winnerTokenId0;
        winners[1] = winnerTokenId1;
        c.pickWinner(winners);

        uint256 beforeRoundId = c.roundId();
        uint32 beforeClaimed = c.numRoundsClaimed(address(this));

        // Caller is winning both slots, so two model entries are needed.
        string[] memory uris = new string[](2);
        string[] memory types = new string[](2);
        uint256[2][] memory attrs = new uint256[2][](2);
        uris[0] = modelURI;
        uris[1] = modelURI;
        types[0] = modelType;
        types[1] = modelType;
        attrs[0] = [attr0, attr1];
        attrs[1] = [attr0, attr1];

