contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 winner1, uint256 winner2) public payable {
        // ensure exactly the configured number of winners are passed;
        // we pass 2 which is the initial winnersPerPeriod value in C
        require(winner1 != winner2, "winners must be distinct");

        // read initial roundId and winnersPerPeriod through public getters
        uint256 roundIdBefore = c.roundId();
        uint256 winnersPerPeriodBefore = c.winnersPerPeriod();
        require(winnersPerPeriodBefore == 2, "test assumes initial winnersPerPeriod == 2");

        // pickWinner must be called as admin (msg.sender is InvMutTest contract)
        // The test invariant assumes InvMutTest is an admin of c.
        uint256[] memory winners = new uint256[](2);
        winners[0] = winner1;
        winners[1] = winner2;

        // The call may revert (e.g. not admin, nonexistent token id, etc.)
        bool reverted = false;
        try c.pickWinner(winners) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read state after the call
        uint256 roundIdAfter = c.roundId();
        bool selectionCompleteAfter = c.isSelectionComplete(roundIdBefore);

        // General rule: if the call succeeds, roundId increases by exactly one
        // and the just-finished round is marked complete.
        // If the call reverts, none of these state changes occur.
        assert(
            (reverted && roundIdAfter == roundIdBefore && !selectionCompleteAfter) ||
            (!reverted && roundIdAfter == roundIdBefore + 1 && selectionCompleteAfter)
        );
    }

    receive() external payable {}
}

