    constructor(C _c) { c = _c; }

    function run(uint256 tokenA, uint256 tokenB, uint256 pointsA, uint256 pointsB) public payable {
        require(address(this).balance >= pointsA + pointsB);
        require(pointsA + pointsB <= type(uint256).max);

        c.addPoints{value: pointsA + pointsB}(tokenA, pointsA);
        c.addPoints{value: pointsA + pointsB}(tokenB, pointsB);

        uint256 totalBefore = c.totalPoints();
        uint256 pointsABefore = c.fighterPoints(tokenA);
        uint256 pointsBBefore = c.fighterPoints(tokenB);

        uint256 sumBefore = pointsABefore + pointsBBefore;
        require(sumBefore <= totalBefore);

        uint256[] memory winners = new uint256[](2);
        winners[0] = tokenA;
        winners[1] = tokenB;

        bool reverted;
        try c.pickWinner(winners) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 totalAfter = c.totalPoints();
        uint256 pointsAAfter = c.fighterPoints(tokenA);
        uint256 pointsBAfter = c.fighterPoints(tokenB);

        if (!reverted) {
            assert(pointsAAfter == 0 && pointsBAfter == 0);
            assert(totalAfter == totalBefore - pointsABefore - pointsBBefore);
        } else {
            assert(pointsAAfter == pointsABefore && pointsBAfter == pointsBBefore);
            assert(totalAfter == totalBefore);
        }
    }
}

