    function run(address caller, uint256 newWinnersPerPeriodAmount) public {
        // We can only influence the caller indirectly: in this test harness the calls
        // to c are executed by this test contract, so we must use the existing
        // admin access control state. The contract's admin set is controlled by
        // adjustAdminAccess, which is itself owner-gated, so we cannot grant
        // arbitrary senders. Instead, we test that the *function* is gated by the
        // admin flag by reading it back from the public getter `isAdmin`.
        //
        // Precondition: isAdmin[address(this)] must be true for a successful call,
        // which is established at construction: isAdmin[_ownerAddress] = true.
        // Since c was deployed by this test contract, the constructor's owner is
        // this test contract, so address(this) has admin rights in the fresh c.

        // Read the admin flag before the call through the public getter, if it is
        // not the test contract itself. Since we cannot vary msg.sender, we only
        // depend on the actual msg.sender being an admin.
        bool adminBefore = c.isAdmin(address(this));
        require(adminBefore, "test harness is not admin");

        // Drive the setter. As admin, this must not revert and must update the
        // value to exactly the provided argument.
        c.updateWinnersPerPeriod(newWinnersPerPeriodAmount);

        // Assert the general rule: after an admin call, winnersPerPeriod equals
        // the argument, regardless of the previous value.
        assert(c.winnersPerPeriod() == newWinnersPerPeriodAmount);
    }
}

