contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256[] calldata winners) public payable {
        // Precondition: number of winners must match winnersPerPeriod and must not be empty.
        require(winners.length == c.winnersPerPeriod());
        require(winners.length > 0);

        // Read the sum of current fighterPoints for the selected winner token IDs before pickWinner.
        uint256 sumBefore = 0;
        for (uint256 i = 0; i < winners.length; i++) {
            sumBefore += c.fighterPoints(winners[i]);
        }

        uint256 totalBefore = c.totalPoints();

        // Drive the deciding call.
        bool reverted;
        try c.pickWinner(winners) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            uint256 totalAfter = c.totalPoints();
            // General rule: totalPoints decreases by exactly the summed previous points.
            assert(totalAfter == totalBefore - sumBefore);
        } else {
            // If pickWinner reverts, totalPoints must not change.
            assert(c.totalPoints() == totalBefore);
        }
    }

    receive() external payable {}
}

