contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 winner1, uint256 winner2) public {
        address admin = msg.sender;

        // pickWinner requires contract isAdmin[msg.sender]; every call from the test is msg.sender
        // and the deployer of c is this test contract, which is recorded as isAdmin at deployment only
        // for the owner passed in the constructor. The checker doesn't expose the owner, so instead
        // we drive the claimRewards path and assert the invariant that for ANY address the number of
        // claimed rounds is bounded by the number of rounds that exist (roundId).
        // claimRewards is nonReentrant and has no priviledged gate, so it can be called by us directly.

        uint256 roundIdBefore = c.roundId();
        uint256 claimedBefore = c.numRoundsClaimed(address(this));

        bool reverted;
        string[] memory modelURIs = new string[](0);
        string[] memory modelTypes = new string[](0);
        uint256[2][] memory customAttributes = new uint256[2][](0);
        try c.claimRewards(modelURIs, modelTypes, customAttributes) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 claimedAfter = c.numRoundsClaimed(address(this));
        uint256 roundIdAfter = c.roundId();

        // General rule: whatever happened, the caller's numRoundsClaimed can never exceed the
        // total number of rounds, and can never decrease across the claimRewards call.
        assert(claimedAfter <= roundIdAfter && claimedAfter >= claimedBefore);
    }
}
